values
  ($q$general$q$, $q$choice$q$, 1, null, $q$Which planet is known as the Red Planet?$q$, $q$["Venus", "Mars", "Jupiter", "Saturn"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Mars$q$, $q$It is also known as the "Red Planet", for its orange-red appearance.$q$, null, null),
  ($q$general$q$, $q$choice$q$, 1, null, $q$What is the largest ocean on Earth?$q$, $q$["Atlantic", "Indian", "Pacific", "Arctic"]$q$::jsonb, $q${"option": 2}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Pacific_Ocean$q$, $q$The Pacific Ocean is the largest and deepest of Earth's five oceanic divisions.$q$, null, null),
  ($q$general$q$, $q$choice$q$, 2, null, $q$Which gas do plants take in from the air to make food by photosynthesis?$q$, $q$["Oxygen", "Carbon dioxide", "Nitrogen", "Hydrogen"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Photosynthesis$q$, $q$== Overview == Most photosynthetic organisms are photoautotrophs, which means that they are able to synthesize food directly from carbon dioxide and water using energy from light.$q$, null, null),
  ($q$general$q$, $q$true_false$q$, 2, null, $q$The Great Wall of China can be seen from the Moon with the naked eye.$q$, null, $q${"value": false}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Great_Wall_of_China$q$, $q$=== From the Moon === The Great Wall of China cannot be seen by the naked human eye from the Moon which orbits around Earth at an average distance of 384,399 kilometres (238,854 mi).$q$, null, null),
  ($q$general$q$, $q$estimate$q$, 2, null, $q$How many bones are there in the adult human body?$q$, null, $q${"value": 206}$q$::jsonb, $q$bones$q$, $q$https://en.wikipedia.org/wiki/Human_skeleton$q$, $q$It is composed of around 270 bones at birth – this total decreases to around 206 bones by adulthood after some bones fuse together, not counting accessory bones.$q$, null, null),
  ($q$general$q$, $q$estimate$q$, 1, null, $q$In what year did people first land on the Moon?$q$, null, $q${"value": 1969}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Apollo_11$q$, $q$Apollo 11 (July 16–24, 1969) was the American spaceflight that first landed humans on the Moon, and the fifth crewed mission of NASA's Apollo program.$q$, null, null),
  ($q$general$q$, $q$estimate$q$, 3, null, $q$How tall is Mount Everest, in metres?$q$, null, $q${"value": 8848.86}$q$::jsonb, $q$metres$q$, $q$https://en.wikipedia.org/wiki/Mount_Everest$q$, $q$Its height was most recently measured in 2020 through a joint survey by Nepalese and Chinese authorities as 8,848.86 m (29,031 ft 8+1⁄2 in).$q$, null, null),
  ($q$geography$q$, $q$choice$q$, 1, null, $q$What is the capital of Australia?$q$, $q$["Sydney", "Melbourne", "Canberra", "Perth"]$q$::jsonb, $q${"option": 2}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Canberra$q$, $q$Canberra ( KAN-brə; Ngunawal: Kanbarra) is the capital city of Australia and the largest population centre in the Australian Capital Territory.$q$, null, null),
  ($q$geography$q$, $q$choice$q$, 1, null, $q$What is the capital of Canada?$q$, $q$["Toronto", "Ottawa", "Vancouver", "Montreal"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Ottawa$q$, $q$Ottawa ( , ; Canadian French: [ɔtawɑ] ) is the capital city of Canada.$q$, null, null),
  ($q$geography$q$, $q$choice$q$, 2, null, $q$Which is the largest hot desert in the world?$q$, $q$["Gobi", "Sahara", "Kalahari", "Thar"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Sahara$q$, $q$With an area of 9,200,000 square kilometres (3,600,000 sq mi), it is the largest hot desert in the world and the third-largest desert overall, smaller only than the deserts of Antarctica and the northern Arctic.$q$, null, null),
  ($q$geography$q$, $q$true_false$q$, 2, null, $q$Mount Kilimanjaro is in Kenya.$q$, null, $q${"value": false}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Mount_Kilimanjaro$q$, $q$Mount Kilimanjaro () is a large dormant stratovolcano in Tanzania.$q$, null, null),
