  ($q$science$q$, $q$estimate$q$, 3, null, $q$How many elements are there on the periodic table?$q$, null, $q${"value": 118}$q$::jsonb, $q$elements$q$, $q$https://en.wikipedia.org/wiki/Periodic_table$q$, $q$By 2010, the first 118 elements were known, thereby completing the first seven rows of the table; however, chemical characterization is still needed for the heaviest elements to confirm that their properties match their positions.$q$, null, null),
  ($q$cricket$q$, $q$choice$q$, 1, null, $q$How many players does each cricket team have on the field?$q$, $q$["9", "10", "11", "12"]$q$::jsonb, $q${"option": 2}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Cricket$q$, $q$Cricket is a bat-and-ball game that is played between two teams of eleven players on a field, at the centre of which is a 22-yard (20-metre; 66-foot) pitch with a wicket at each end, each comprising two bails (small sticks) balanced on three stumps.$q$, null, null),
  ($q$cricket$q$, $q$choice$q$, 2, null, $q$Who won the first Cricket World Cup, in 1975?$q$, $q$["England", "India", "West Indies", "Australia"]$q$::jsonb, $q${"option": 2}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/1975_Cricket_World_Cup$q$, $q$After Australia defeated England and the West Indies defeated New Zealand in the semi-finals, the West Indies which came into the tournament as favourites, defeated Australia in the final at Lord's by 17 runs to become the first World Cup winners.$q$, null, null),
  ($q$cricket$q$, $q$true_false$q$, 2, null, $q$A cricket pitch is 22 yards long.$q$, null, $q${"value": true}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Cricket_pitch$q$, $q$It is 22 yd (20.12 m) long (1 chain) and 10 ft (3.05 m) wide.$q$, null, null),
