  ($q$food$q$, $q$choice$q$, 1, null, $q$What is the main ingredient of guacamole?$q$, $q$["Avocado", "Tomato", "Peas", "Cucumber"]$q$::jsonb, $q${"option": 0}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Guacamole$q$, $q$Guacamole (Spanish: [ɡwakaˈmole] ), sometimes informally shortened to guac in the United States, is an avocado-based dip, spread, or salad first developed in Mexico.$q$, null, null),
  ($q$food$q$, $q$true_false$q$, 2, null, $q$Sushi rice is seasoned with vinegar.$q$, null, $q${"value": true}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Sushi$q$, $q$Sushi (すし, 寿司, 鮨, 鮓; pronounced [sɯɕiꜜ] or [sɯꜜɕi] ) is a traditional Japanese dish made with vinegared rice (鮨飯, sushi-meshi), typically seasoned with sugar and salt, and combined with a variety of ingredients (ねた, neta), such as seafood, vegetables, or meat; raw seafood is the most common, although some may be cooked.$q$, null, null),
  ($q$music$q$, $q$choice$q$, 1, null, $q$How many keys does a standard modern piano have?$q$, $q$["76", "88", "92", "100"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Piano$q$, $q$Most modern pianos have 52 white keys and 36 black keys, for a total of 88 keys (seven octaves plus a minor third, from A0 to C8).$q$, null, null),
