  ($q$music$q$, $q$true_false$q$, 1, null, $q$A violin has four strings.$q$, null, $q${"value": true}$q$::jsonb, null, $q$https://en.wikipedia.org/wiki/Violin$q$, $q$Most violins have a hollow wooden body, and commonly have four strings (sometimes five), usually tuned in perfect fifths with notes G3, D4, A4, E5, and are most commonly played by drawing a bow across the strings.$q$, null, null),
  ($q$science$q$, $q$picture$q$, 1, null, $q$Which planet is this?$q$, $q$["Jupiter", "Saturn", "Uranus", "Neptune"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://commons.wikimedia.org/wiki/File:Saturn_during_Equinox.jpg$q$, $q$This natural color view of the planet Saturn was created from images collected shortly after Cassini began its extended Equinox Mission in July 2008. (Saturn actually reached equinox on August 11, 2009.)$q$, $q$4b7ff46425c55aca4e31be89ee4c04c7.jpg$q$, $q${"author": "NASA / JPL / Space Science Institute", "licence": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:Saturn_during_Equinox.jpg"}$q$::jsonb),
  ($q$science$q$, $q$picture$q$, 2, null, $q$Which planet is this?$q$, $q$["Mars", "Jupiter", "Saturn", "Neptune"]$q$::jsonb, $q${"option": 1}$q$::jsonb, null, $q$https://commons.wikimedia.org/wiki/File:Jupiter_and_its_shrunken_Great_Red_Spot.jpg$q$, $q$This full-disc image of Jupiter was taken on 21 April 2014 with Hubble's Wide Field Camera 3 (WFC3).$q$, $q$c40306b066f21da214e171f076aea57d.jpg$q$, $q${"author": "NASA, ESA, and A. Simon (Goddard Space Flight Center)", "licence": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:Jupiter_and_its_shrunken_Great_Red_Spot.jpg"}$q$::jsonb),
  ($q$geography$q$, $q$picture$q$, 1, null, $q$Which country's flag is this?$q$, $q$["India", "Niger", "Ireland", "Italy"]$q$::jsonb, $q${"option": 0}$q$::jsonb, null, $q$https://commons.wikimedia.org/wiki/File:Flag_of_India.svg$q$, $q$The Flag of India. The colours are saffron, white and green. The navy blue wheel in the center of the flag has a diameter approximately the width of the white band and is called Ashoka's Dharma Chakra, with 24 spokes (after Ashoka, the Great). Each spoke depicts one hour of the day, portraying the prevalence of righteousness all 24 hours of it.$q$, $q$69074216b8dbaf8c382cd7a2dc941a3f.png$q$, $q${"author": "Government of India", "licence": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:Flag_of_India.svg"}$q$::jsonb),
  ($q$geography$q$, $q$picture$q$, 1, null, $q$Which country's flag is this?$q$, $q$["Japan", "Bangladesh", "South Korea", "China"]$q$::jsonb, $q${"option": 0}$q$::jsonb, null, $q$https://commons.wikimedia.org/wiki/File:Flag_of_Japan.svg$q$, $q$Flag of Japan$q$, $q$4ab4211b473b0142e4a2a59eb2e4a042.png$q$, $q${"author": "Various", "licence": "Public domain", "source_url": "https://commons.wikimedia.org/wiki/File:Flag_of_Japan.svg"}$q$::jsonb),
